import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";

export default function Biology() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);

  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  useEffect(() => {
    async function load() {
      try {
        const res = await fetch("http://localhost:8080/resources");
        const data = await res.json();
        const found = (data.subsciences || []).find((s) => /bio/i.test(s.name) || s.code === "biology");
        setSub(found || null);

        if (found) {
          // try to fetch lessons for this subscience for the current user
          try {
            const lid = user ? user.id : "";
            const lres = await fetch(`http://localhost:8080/subsciences/${found.id}/lessons/${lid}`);
            const ldata = await lres.json();
            const fetched = ldata.lessons || [];

            // detect first visit for this user+subscience using localStorage
            const visitedKey = `visited_sub_${found.id}_user_${user?.id || "guest"}`;
            const firstVisit = !localStorage.getItem(visitedKey);

            // ensure there are 10 lessons (pad if backend doesn't provide)
            const pad = [];
            for (let i = 1; i <= 10; i++) {
              const ex = fetched.find((f) => f.lesson_number === i);
              // if first visit, force lessons locked (preview separate)
              if (firstVisit) {
                pad.push(ex ? { ...ex, status: "locked" } : { id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "locked" });
              } else {
                pad.push(ex || { id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "locked" });
              }
            }

            // mark visited so next time we respect backend progress
            if (firstVisit) localStorage.setItem(visitedKey, Date.now().toString());

            setLessons(pad);
          } catch (err) {
            // fallback: create 10 locked lessons
            const pad = [];
            for (let i = 1; i <= 10; i++) pad.push({ id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "locked" });
            setLessons(pad);
          }
        } else {
          // no resources/subscience found: still show 10 lessons in "schedule locked" mode
          const pad = [];
          for (let i = 1; i <= 10; i++) pad.push({ id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "schedule_locked" });
          setLessons(pad);
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [user]);

  function markIntroWatched() {
    // require resources/subscience selection before unlocking lessons
    if (!sub) {
      alert("Please select resources for this unit before unlocking lessons.");
      return;
    }

    // mark lesson 1 as unlocked locally; attempt backend call if lesson has real id
    setLessons((prev) => prev.map((ls) => (ls.lesson_number === 1 ? { ...ls, status: "unlocked" } : ls)));
    const lesson = lessons.find((l) => l.lesson_number === 1);
    if (lesson && !String(lesson.id).startsWith("local-")) {
      fetch(`http://localhost:8080/lesson_progress/unlock`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user?.id, lesson_id: lesson.id }),
      }).catch((e) => console.warn("Could not persist unlock:", e));
    }
  }

  async function openLessonDetails(lesson) {
    setSelectedLesson(lesson);
    setShowLessonModal(true);
    setLessonTutors([]);
    setLessonSessions([]);

    try {
      const tRes = await fetch(`http://localhost:8080/lessons/${lesson.id}/tutors`);
      const tData = await tRes.json();
      setLessonTutors(tData.tutors || []);
    } catch (err) {
      console.error("Failed to load tutors", err);
    }

    try {
      const sRes = await fetch(`http://localhost:8080/lessons/${lesson.id}/sessions`);
      const sData = await sRes.json();
      const normalized = (sData.sessions || []).map((ss) => ({
        ...ss,
        spots_left: ss.max_spots - (ss.signed_up_count || ss.signed_up || 0),
      }));
      setLessonSessions(normalized);
    } catch (err) {
      console.error("Failed to load sessions", err);
    }
  }

  async function handleSignupToSession(session) {
    const userLocal = JSON.parse(localStorage.getItem("user"));
    if (!userLocal) {
      alert("Please log in to join a session");
      return;
    }

    if (session.spots_left === 0) {
      alert("This session is full");
      return;
    }

    setSignupProcessing(true);
    try {
      const res = await fetch(`http://localhost:8080/sessions/${session.id}/signup`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: userLocal.id, name: userLocal.firstName, email: userLocal.email }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || "Signup failed");
      alert(data.message || "Signed up for session");
      setLessonSessions((prev) => prev.map((p) => (p.id === session.id ? { ...p, spots_left: Math.max(0, (p.spots_left || p.max_spots) - 1) } : p)));
    } catch (err) {
      console.error(err);
      alert(err.message || "Signup error");
    } finally {
      setSignupProcessing(false);
    }
  }

  return (
    <div className="dashboard-page">
      <Sidebar />
      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Biology</h1>
            <p className="dashboard-subtitle">Discover living systems, cells, genetics and ecology.</p>
          </div>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading...</p>
        ) : (
          <div>
            {!sub && (
              <div className="card" style={{ marginBottom: 12 }}>
                <p className="muted">
                  No resources selected for this unit — lessons are schedule-locked.
                  <button className="btn" onClick={() => navigate("/resources")} style={{ marginLeft: 8 }}>
                    Select Resources
                  </button>
                </p>
              </div>
            )}

            {/* Intro video */}
            <section className="card" style={{ marginBottom: 16 }}>
              <h2>Intro to Biology</h2>
              <div style={{ position: "relative", paddingBottom: "56.25%", height: 0 }}>
                <iframe
                  title="Biology Intro"
                  src="https://www.youtube.com/embed/PWGBqskV1UQ?rel=0"
                  style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}
                  frameBorder="0"
                  allowFullScreen
                />
              </div>
                <div style={{ marginTop: 12 }}>
                <button className="primary-btn" onClick={markIntroWatched}>I've finished watching</button>
                <button
                  className="btn"
                  style={{ marginLeft: 8 }}
                  onClick={() => (sub ? navigate(`/subscience/${sub.id}`) : navigate(`/resources`))}
                >
                  {sub ? "Open Unit Page" : "Select Resources"}
                </button>
              </div>
            </section>

            {/* Lessons list */}
            <section className="dashboard-panel">
              <h2>Lessons</h2>
              <ul className="subscience-lessons-list">
                {lessons.map((lesson) => (
                  <li key={lesson.id} className={`subscience-lesson ${lesson.status}`}>
                    <div className="subscience-lesson-main">
                      <div>
                        <p className="subscience-lesson-number">Lesson {lesson.lesson_number}</p>
                        <p className="subscience-lesson-title">{lesson.title}</p>
                        <p className="subscience-lesson-status">Status: {lesson.status}</p>
                      </div>

                      <div className="subscience-lesson-tags">
                        {lesson.status === "completed" && <span className="tag tag-completed">Completed</span>}
                        {lesson.status === "unlocked" && <span className="tag tag-unlocked">Ready</span>}
                        {lesson.status === "locked" && <span className="tag tag-locked">Locked</span>}
                        {lesson.status === "schedule_locked" && <span className="tag tag-locked">Schedule</span>}
                      </div>
                    </div>

                    <div className="subscience-lesson-actions">
                      <div style={{ display: "flex", gap: 8 }}>
                        <button className="lesson-action-btn" disabled={lesson.status === "locked" || lesson.status === "schedule_locked"} onClick={() => navigate(`/lesson/${lesson.id}`, { state: { lesson, subId: sub?.id } })}>View Lesson</button>
                        <button className="secondary-btn" disabled={lesson.status === "locked" || lesson.status === "schedule_locked"} onClick={() => openLessonDetails(lesson)}>Tutors & Sessions</button>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            </section>

            {/* Lesson details modal */}
            {showLessonModal && selectedLesson && (
              <div className="modal-overlay" onClick={() => setShowLessonModal(false)}>
                <div className="modal-card" onClick={(e) => e.stopPropagation()}>
                  <h2>Lesson {selectedLesson.lesson_number}: {selectedLesson.title}</h2>
                  <p className="muted">Pick a tutor or join an upcoming session.</p>

                  <div style={{ display: "flex", gap: 16, marginTop: 12 }}>
                    <div style={{ flex: 1 }}>
                      <h3>Tutors</h3>
                      {lessonTutors.length === 0 ? (
                        <p className="muted">No tutors listed for this lesson.</p>
                      ) : (
                        <ul>
                          {lessonTutors.map((t) => (
                            <li key={t.id} style={{ marginBottom: 8 }}>
                              <strong>{t.name}</strong>
                              <p className="muted">{t.bio}</p>
                            </li>
                          ))}
                        </ul>
                      )}
                    </div>

                    <div style={{ flex: 1 }}>
                      <h3>Upcoming Sessions</h3>
                      {lessonSessions.length === 0 ? (
                        <p className="muted">No sessions scheduled yet.</p>
                      ) : (
                        <ul>
                          {lessonSessions.map((s) => (
                            <li key={s.id} style={{ marginBottom: 10 }}>
                              <div style={{ display: "flex", justifyContent: "space-between" }}>
                                <div>
                                  <p><strong>{new Date(s.session_time).toLocaleString()}</strong></p>
                                  <p className="muted">Tutor: {s.tutor_name || s.tutorName}</p>
                                  <p className="muted">Spots: {s.spots_left ?? (s.max_spots - (s.signed_up || 0))} / {s.max_spots}</p>
                                </div>

                                <div style={{ alignSelf: "center" }}>
                                  <button className="primary-btn" disabled={signupProcessing || (s.spots_left === 0)} onClick={() => handleSignupToSession(s)}>Join</button>
                                </div>
                              </div>
                            </li>
                          ))}
                        </ul>
                      )}
                    </div>
                  </div>

                  <div style={{ marginTop: 16, textAlign: "right" }}>
                    <button className="btn" onClick={() => setShowLessonModal(false)}>Close</button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
}
